import{_ as a,o as e,c as r,ae as o}from"./chunks/framework.RRduUuAx.js";const _=JSON.parse('{"title":"数据结构复习（示例）","description":"","frontmatter":{},"headers":[],"relativePath":"cs/data-structures.md","filePath":"cs/data-structures.md"}'),d={name:"cs/data-structures.md"};function l(s,t,c,i,n,h){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="数据结构复习-示例" tabindex="-1">数据结构复习（示例） <a class="header-anchor" href="#数据结构复习-示例" aria-label="Permalink to &quot;数据结构复习（示例）&quot;">​</a></h1><blockquote><p>以下为课堂还原式摘要，非严谨教材。</p></blockquote><h2 id="_1-栈与队列" tabindex="-1">1. 栈与队列 <a class="header-anchor" href="#_1-栈与队列" aria-label="Permalink to &quot;1. 栈与队列&quot;">​</a></h2><ul><li><strong>栈</strong>：后进先出（LIFO）。典型用途：括号匹配、DFS 手写栈。</li><li><strong>队列</strong>：先进先出（FIFO）。典型用途：BFS、滑动窗口辅助。</li></ul><h2 id="_2-哈希表" tabindex="-1">2. 哈希表 <a class="header-anchor" href="#_2-哈希表" aria-label="Permalink to &quot;2. 哈希表&quot;">​</a></h2><p>平均 <code>O(1)</code> 查找的依据是：<strong>负载因子</strong>可控且哈希函数近似均匀。</p><p>冲突处理简述：</p><table tabindex="0"><thead><tr><th>策略</th><th>要点</th></tr></thead><tbody><tr><td>链地址法</td><td>桶内链表/向量</td></tr><tr><td>开放寻址</td><td>探测序列；删除需惰性标记</td></tr></tbody></table><h2 id="_3-二叉搜索树" tabindex="-1">3. 二叉搜索树 <a class="header-anchor" href="#_3-二叉搜索树" aria-label="Permalink to &quot;3. 二叉搜索树&quot;">​</a></h2><p>中序遍历得到升序序列（在无重复键的简化模型下）。</p><div class="warning custom-block"><p class="custom-block-title">注意</p><p>随机 BST 期望高度 <code>O(log n)</code>；退化链为 <code>O(n)</code>。实用结构常选红黑树、AVL、B 树家族。</p></div><h2 id="练习-占位" tabindex="-1">练习（占位） <a class="header-anchor" href="#练习-占位" aria-label="Permalink to &quot;练习（占位）&quot;">​</a></h2><ol><li>给定数组，求下一个更大元素——单调栈模板。</li><li>实现 LRU：哈希表 + 双向链表（或 OrderedDict 思路）。</li></ol>',13)])])}const p=a(d,[["render",l]]);export{_ as __pageData,p as default};
